  chunks[#chunks+1]=table.concat(t);i=upper+1
 end
 return table.concat(chunks)
end
local function start()
 local raw=inflate(unpack85(packed,58449))
 if #raw~=UN58449 then error("Unpack size mismatch: "..#raw) end
 local run,err=loadstring(raw)
 if not run then error("LEGACY MOBILE COMPILE: "..tostring(err)) end
 return run()
end
