  label.Size=UDim2.new(1,-20,0,120);label.Position=UDim2.fromOffset(10,60);label.BackgroundColor3=Color3.fromRGB(120,20,30);label.TextColor3=Color3.new(1,1,1);label.TextWrapped=true;label.TextSize=15;label.Text="LEGACY PACKED ERROR: "..tostring(err):sub(1,500);label.Parent=gui
 end)
